#[inline(always)]
fn affine_offset_g2_finish(s:&[FqBatch;2],ax:&[FqBatch;2],bx:&[FqBatch;2],ay:&[FqBatch;2])->([FqBatch;2],[FqBatch;2]){
    let x=[s[0].add(&s[1]).affine_mul_minus_sum(&s[0].sub(&s[1]),&ax[0],&bx[0]),s[0].affine_mul_double_minus_sum(&s[1],&ax[1],&bx[1])];
    let dx=[ax[0].sub(&x[0]),ax[1].sub(&x[1])];
    let y=[s[0].affine_difference2_minus(&dx[0],&s[1],&dx[1],&ay[0]),s[0].affine_sum2_minus(&dx[1],&s[1],&dx[0],&ay[1])];
    (x,y)
}

